record.field:
type_document_code = ' '
if object.partner_id and object.partner_id.l10n_latam_identification_type_id:
    type_document = object.partner_id.l10n_latam_identification_type_id
    if type_document.id == env.ref('l10n_co.national_citizen_id').id:
        type_document_code = '1'
    elif type_document.id == env.ref('l10n_co.foreign_resident_card').id:
        type_document_code = '2'
    elif type_document.id == env.ref('l10n_co.rut').id:
        type_document_code = '3'
    elif type_document.id == env.ref('l10n_co.id_card').id:
        type_document_code = '4'
    elif type_document.id == env.ref('l10n_latam_base.it_pass').id:
        type_document_code = '5'
result = type_document_code

beneficiary_nit = ' '
if object.partner_id and object.partner_id.vat and object.partner_id.l10n_latam_identification_type_id:
    type_document = object.partner_id.l10n_latam_identification_type_id
    if type_document.id == env.ref('l10n_co.rut').id:
        beneficiary_nit = object.partner_id.ref or object.partner_id.vat
    else:
        beneficiary_nit = object.partner_id.vat
    # Remove non-numeric characters and truncate to 15 digits as per Bancolombia spec
    if beneficiary_nit:
        beneficiary_nit = ''.join(filter(str.isdigit, str(beneficiary_nit)))
        if len(beneficiary_nit) > 15:
            beneficiary_nit = beneficiary_nit[:15]
result = beneficiary_nit

beneficiary_name = ' '
if object.partner_id and object.partner_id.display_name:
    beneficiary_name = object.partner_id.display_name.upper()
    # Replace special characters
    if 'Ñ' in beneficiary_name:
        beneficiary_name = beneficiary_name.replace('Ñ', 'N')
    # Truncate to 30 characters as per Bancolombia spec
    if len(beneficiary_name) > 30:
        beneficiary_name = beneficiary_name[:30]
result = beneficiary_name
